  <meta property="twitter:description" content="Unique flavors, quality ingredients, and unbeatable prices — all waiting for you at your neighborhood Fresh Pantry.">
  <meta property="twitter:image" content="https://freshpantry.com/og-image.jpg">

  <link rel="icon" type="image/svg+xml" href="favicon.svg">
  <link rel="icon" type="image/png" sizes="32x32" href="favicon-32.png">
  <link rel="apple-touch-icon" href="apple-touch-icon.png">

  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800&family=Poppins:wght@400;500;600&display=swap" rel="stylesheet">

  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "GroceryStore",
    "name": "Fresh Pantry",
    "image": "https://freshpantry.com/og-image.jpg",
    "description": "Your neighborhood grocery store reimagined — a place where quality meets affordability and every aisle holds a delicious surprise.",
    "@id": "https://freshpantry.com/#organization",
    "url": "https://freshpantry.com",
    "telephone": "+1-800-FRESH-PT",
    "priceRange": "$$",
    "address": {
      "@type": "PostalAddress",
      "addressLocality": "Chicago",
      "addressRegion": "IL",
      "addressCountry": "US"
    },
    "areaServed": [
      { "@type": "State", "name": "Illinois" },
      { "@type": "State", "name": "California" },
      { "@type": "State", "name": "New York" },
      { "@type": "State", "name": "Texas" }
    ],
    "sameAs": [
      "https://www.instagram.com/freshpantry",
      "https://www.facebook.com/freshpantry",
      "https://www.pinterest.com/freshpantry",
      "https://www.tiktok.com/@freshpantry"
    ]
  }
  </script>

  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --primary: #2D6A4F;
      --primary-dark: #1e4d38;
      --accent: #F4A261;
      --accent-hover: #e8924d;
      --background: #FEFAE0;
      --card-bg: #ffffff;
      --text: #2c3e50;
      --text-light: #5a6c7d;
      --shadow: 0 4px 20px rgba(45, 106, 79, 0.1);
      --shadow-hover: 0 8px 30px rgba(45, 106, 79, 0.15);
      --radius: 16px;
      --radius-sm: 10px;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Poppins', -apple-system, BlinkMacSystemFont, sans-serif;
      background-color: var(--background);
      color: var(--text);
      line-height: 1.6;
    }

    h1, h2, h3, h4, h5, h6 {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      line-height: 1.2;
    }

    a {
      text-decoration: none;
      color: inherit;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Header */
    header {
      background: var(--card-bg);
      padding: 16px 0;
      position: sticky;
      top: 0;
      z-index: 100;
      box-shadow: var(--shadow);
    }

    header .container {
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .logo {
      font-family: 'Nunito', sans-serif;
      font-size: 1.75rem;
      font-weight: 800;
      color: var(--primary);
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--primary);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 24px;
      height: 24px;
      fill: white;
    }

    nav ul {
      display: flex;
      list-style: none;
      gap: 32px;
    }

    nav a {
      font-weight: 500;
      color: var(--text);
      transition: color 0.2s;
      position: relative;
    }

    nav a::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--accent);
      transition: width 0.3s;
    }

    nav a:hover {
      color: var(--primary);
    }

    nav a:hover::after {
      width: 100%;
    }

    .mobile-menu-btn {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }

    /* Hero */
    .hero {
      padding: 80px 0 100px;
      text-align: center;
      background: linear-gradient(135deg, var(--background) 0%, #f5f0d8 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(244, 162, 97, 0.15) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -30%;
      left: -10%;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(45, 106, 79, 0.1) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero h1 {
      font-size: clamp(2.5rem, 5vw, 4rem);
      color: var(--primary);
      margin-bottom: 20px;
      position: relative;
      z-index: 1;
    }

    .hero p {
      font-size: 1.2rem;
      color: var(--text-light);
      max-width: 600px;
      margin: 0 auto 40px;
      position: relative;
      z-index: 1;
    }

    .hero-buttons {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
      position: relative;
      z-index: 1;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 28px;
      border-radius: 50px;
      font-weight: 600;
      font-size: 1rem;
      cursor: pointer;
      transition: all 0.3s;
      border: none;
    }

    .btn-primary {
      background: var(--primary);
      color: white;
    }

    .btn-primary:hover {
      background: var(--primary-dark);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(45, 106, 79, 0.3);
    }

    .btn-secondary {
      background: var(--accent);
      color: white;
    }

    .btn-secondary:hover {
      background: var(--accent-hover);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(244, 162, 97, 0.3);
    }

    /* Brand Stats Banner */
    .brand-stats {
      background: var(--primary);
      padding: 60px 0;
    }

    .brand-stats .container {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
    }

    .stat-item {
      text-align: center;
      color: white;
    }

    .stat-number {
      font-family: 'Nunito', sans-serif;
      font-size: 3rem;
      font-weight: 800;
      display: block;
      margin-bottom: 8px;
    }

    .stat-label {
      font-size: 0.95rem;
      opacity: 0.9;
    }

    /* Section Styles */
    section {
      padding: 80px 0;
    }

    .section-title {
      font-size: 2.2rem;
      color: var(--primary);
      text-align: center;
      margin-bottom: 16px;
    }

    .section-subtitle {
      text-align: center;
      color: var(--text-light);
      max-width: 600px;
      margin: 0 auto 50px;
      font-size: 1.05rem;
    }

    /* Featured Products Carousel */
    .featured-products {
      background: var(--card-bg);
    }

    .carousel-container {
      position: relative;
      max-width: 1000px;
      margin: 0 auto;
    }

    .carousel-track {
      display: flex;
      gap: 24px;
      overflow-x: hidden;
      scroll-behavior: smooth;
      scrollbar-width: none;
      -ms-overflow-style: none;
      padding: 20px 0;
    }

    .carousel-track::-webkit-scrollbar {
      display: none;
    }

    .product-card {
      flex: 0 0 calc(25% - 18px);
      min-width: 220px;
      background: var(--background);
      border-radius: var(--radius);
      padding: 20px;
      text-align: center;
      transition: all 0.3s;
    }

    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-hover);
    }

    .product-image {
      width: 100%;
      aspect-ratio: 1;
      background: #f0ebe0;
      border-radius: var(--radius-sm);
      margin-bottom: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
    }

    .product-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1.1rem;
      margin-bottom: 6px;
      color: var(--text);
    }

    .product-desc {
      font-size: 0.85rem;
      color: var(--text-light);
      margin-bottom: 12px;
      line-height: 1.4;
    }

    .product-price {
      font-weight: 600;
      color: var(--primary);
      font-size: 1.15rem;
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--card-bg);
      border: 2px solid var(--primary);
      color: var(--primary);
      font-size: 1.5rem;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all 0.2s;
      z-index: 10;
    }

    .carousel-btn:hover {
      background: var(--primary);
      color: white;
    }

    .carousel-btn.prev {
      left: -24px;
    }

    .carousel-btn.next {
      right: -24px;
    }

    /* Seasonal Picks */
    .seasonal-picks {
      background: linear-gradient(180deg, var(--background) 0%, #f5f0d8 100%);
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .seasonal-card {
      background: var(--card-bg);
      border-radius: var(--radius);
      padding: 24px;
      text-align: center;
      box-shadow: var(--shadow);
      transition: all 0.3s;
    }

    .seasonal-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-hover);
    }

    .seasonal-emoji {
      font-size: 3rem;
      margin-bottom: 16px;
    }

    .seasonal-card h3 {
      font-size: 1rem;
      margin-bottom: 8px;
      color: var(--text);
    }

    .seasonal-card p {
      font-size: 0.9rem;
      color: var(--text-light);
      margin-bottom: 12px;
    }

    .seasonal-price {
      font-weight: 600;
      color: var(--accent);
      font-size: 1.1rem;
    }

    /* Categories */
    .categories {
      background: var(--card-bg);
    }

    .category-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 20px;
    }

    .category-card {
      position: relative;
      aspect-ratio: 1;
      background: var(--background);
      border-radius: var(--radius);
      overflow: hidden;
      cursor: pointer;
      transition: all 0.3s;
    }

    .category-card:hover {
      transform: scale(1.05);
      box-shadow: var(--shadow-hover);
    }

    .category-icon {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 4rem;
      background: linear-gradient(135deg, #f5f0d8 0%, #ebe5d5 100%);
    }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(45, 106, 79, 0.9) 0%, rgba(45, 106, 79, 0.4) 100%);
      display: flex;
      align-items: flex-end;
      justify-content: center;
      padding-bottom: 20px;
      opacity: 0;
      transition: opacity 0.3s;
    }

    .category-card:hover .category-overlay {
      opacity: 1;
    }

    .category-name {
      color: white;
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1.1rem;
    }

    /* Store Locator */
    .store-locator {
      background: var(--background);
    }

    .search-box {
      max-width: 500px;
      margin: 0 auto 40px;
      display: flex;
      gap: 12px;
    }

    .search-box input {
      flex: 1;
      padding: 16px 20px;
      border: 2px solid #e0d9c8;
      border-radius: 50px;
      font-size: 1rem;
      font-family: inherit;
      background: var(--card-bg);
      transition: border-color 0.2s;
    }

    .search-box input:focus {
      outline: none;
      border-color: var(--primary);
    }

    .search-box button {
      padding: 16px 28px;
      white-space: nowrap;
    }

    .store-results {
      max-width: 600px;
      margin: 0 auto;
      display: none;
    }

    .store-results.active {
      display: block;
    }

    .store-card {
      background: var(--card-bg);
      border-radius: var(--radius);
      padding: 24px;
      margin-bottom: 16px;
      box-shadow: var(--shadow);
      display: flex;
      justify-content: space-between;
      align-items: center;
      transition: all 0.3s;
    }

    .store-card:hover {
      box-shadow: var(--shadow-hover);
    }

    .store-info h3 {
      font-size: 1.15rem;
      color: var(--primary);
      margin-bottom: 6px;
    }

    .store-info p {
      color: var(--text-light);
      font-size: 0.9rem;
    }

    .store-meta {
      text-align: right;
    }

    .store-hours {
      font-size: 0.85rem;
      color: var(--text-light);
      margin-bottom: 4px;
    }

    .store-distance {
      font-weight: 600;
      color: var(--accent);
    }

    /* Newsletter */
    .newsletter {
      background: var(--primary);
      color: white;
      text-align: center;
    }

    .newsletter .section-title {
      color: white;
    }

    .newsletter .section-subtitle {
      color: rgba(255, 255, 255, 0.85);
    }

    .newsletter-form {
      max-width: 450px;
      margin: 0 auto;
      display: flex;
      gap: 12px;
    }

    .newsletter-form input {
      flex: 1;
      padding: 16px 20px;
      border: none;
      border-radius: 50px;
      font-size: 1rem;
      font-family: inherit;
    }

    .newsletter-form input:focus {
      outline: none;
    }

    .newsletter-form button {
      background: var(--accent);
      color: white;
      border: none;
      padding: 16px 28px;
      border-radius: 50px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.3s;
    }

    .newsletter-form button:hover {
      background: var(--accent-hover);
      transform: translateY(-2px);
    }

    .newsletter-confirmation {
      display: none;
      margin-top: 20px;
      padding: 16px 24px;
      background: rgba(255, 255, 255, 0.15);
      border-radius: var(--radius);
    }

    .newsletter-confirmation.active {
      display: block;
    }

    /* Footer */
    footer {
      background: var(--primary-dark);
      color: white;
      padding: 60px 0 30px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(3, 1fr);
      gap: 60px;
      margin-bottom: 50px;
    }

    .footer-brand .logo {
      color: white;
      margin-bottom: 16px;
    }

    .footer-brand .logo-icon {
      background: rgba(255, 255, 255, 0.2);
    }

    .footer-tagline {
      opacity: 0.8;
      font-size: 0.95rem;
    }

    .footer-col h4 {
      font-size: 1rem;
      margin-bottom: 20px;
      opacity: 0.6;
      text-transform: uppercase;
      letter-spacing: 1px;
    }

    .footer-col ul {
      list-style: none;
    }

    .footer-col li {
      margin-bottom: 12px;
    }

    .footer-col a {
      opacity: 0.8;
      transition: opacity 0.2s;
    }

    .footer-col a:hover {
      opacity: 1;
    }

    .footer-bottom {
      text-align: center;
      padding-top: 30px;
      border-top: 1px solid rgba(255, 255, 255, 0.1);
      opacity: 0.6;
      font-size: 0.9rem;
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .category-grid {
        grid-template-columns: repeat(3, 1fr);
      }

      .seasonal-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .brand-stats .container {
        grid-template-columns: repeat(2, 1fr);
        gap: 30px;
      }

      .product-card {
        flex: 0 0 calc(33.333% - 16px);
      }
    }

    @media (max-width: 768px) {
      nav ul {
        display: none;
      }

      .mobile-menu-btn {
        display: block;
      }

      .hero {
        padding: 60px 0 80px;
      }

      .brand-stats {
        padding: 40px 0;
      }

      .stat-number {
        font-size: 2.2rem;
      }

      .section-title {
        font-size: 1.8rem;
      }

      section {
        padding: 60px 0;
      }

      .category-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .product-card {
        flex: 0 0 calc(50% - 12px);
        min-width: 160px;
      }

      .carousel-btn {
        display: none;
      }

      .search-box {
        flex-direction: column;
      }

      .search-box button {
        width: 100%;
      }

      .store-card {
        flex-direction: column;
        text-align: center;
        gap: 16px;
      }

      .store-meta {
        text-align: center;
      }

      .newsletter-form {
        flex-direction: column;
      }

      .footer-grid {
        grid-template-columns: 1fr 1fr;
        gap: 40px;
      }
    }

    @media (max-width: 480px) {
      .category-grid {
        grid-template-columns: 1fr 1fr;
        gap: 12px;
      }

      .seasonal-grid {
        grid-template-columns: 1fr;
      }

      .brand-stats .container {
        grid-template-columns: 1fr 1fr;
        gap: 24px;
      }

      .footer-grid {
        grid-template-columns: 1fr;
        gap: 30px;
      }
    }
  </style>
</head>
<body>

  <!-- Header -->
  <header>
    <div class="container">
      <a href="/" class="logo">
        <div class="logo-icon">
          <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/>
          </svg>
        </div>
        Fresh Pantry
      </a>
      <nav>
        <ul>
          <li><a href="#featured-products">Products</a></li>
          <li><a href="#store-locator">Our Stores</a></li>
          <li><a href="#seasonal">Recipes</a></li>
          <li><a href="#about">About Us</a></li>
        </ul>
      </nav>
      <button class="mobile-menu-btn" aria-label="Menu">
        <svg width="24" height="24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M3 12h18M3 6h18M3 18h18"/>
        </svg>
      </button>
    </div>
  </header>

  <!-- Hero -->
  <section class="hero">
    <div class="container">
      <h1>Discover Everyday Deliciousness</h1>
      <p>Unique flavors, quality ingredients, and unbeatable prices — all waiting for you at your neighborhood Fresh Pantry.</p>
      <div class="hero-buttons">
        <a href="#store-locator" class="btn btn-primary">Find a Store Near You</a>
        <a href="#featured-products" class="btn btn-secondary">Explore This Week's Picks</a>
      </div>
    </div>
  </section>

  <!-- Brand Stats Banner -->
  <section class="brand-stats" id="about">
    <div class="container">
      <div class="stat-item">
        <span class="stat-number">500+</span>
        <span class="stat-label">Stores Nationwide</span>
      </div>
      <div class="stat-item">
        <span class="stat-number">4,000+</span>
        <span class="stat-label">Unique Products</span>
      </div>
      <div class="stat-item">
        <span class="stat-number">80%</span>
        <span class="stat-label">Private Label Items</span>
      </div>
      <div class="stat-item">
        <span class="stat-number">New</span>
        <span class="stat-label">Items Every Week</span>
      </div>
    </div>
  </section>

  <!-- Featured Products Carousel -->
  <section class="featured-products" id="featured-products">
    <div class="container">
      <h2 class="section-title">Featured Products</h2>
      <p class="section-subtitle">Staff favorites you won't want to miss — curated with love for your pantry.</p>

      <div class="carousel-container">
        <button class="carousel-btn prev" aria-label="Previous">&#8249;</button>
        <div class="carousel-track">
          <div class="product-card">
            <div class="product-image">🥣</div>
            <div class="product-name">Organic Maple Granola</div>
            <div class="product-desc">Crunchy clusters with real maple syrup and toasted oats</div>
            <div class="product-price">$3.99</div>
