  <script>
    // Product Carousel
    const carousel = document.querySelector('.carousel-track');
    const prevBtn = document.querySelector('.carousel-btn.prev');
    const nextBtn = document.querySelector('.carousel-btn.next');
    const cardWidth = document.querySelector('.product-card').offsetWidth + 24;

    prevBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: -cardWidth * 2, behavior: 'smooth' });
    });

    nextBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: cardWidth * 2, behavior: 'smooth' });
    });

    // Store Locator Search
    const zipInput = document.getElementById('zipInput');
    const searchBtn = document.getElementById('searchBtn');
    const storeResults = document.getElementById('storeResults');

    searchBtn.addEventListener('click', () => {
      if (zipInput.value.trim()) {
        storeResults.classList.add('active');
      }
    });

    zipInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        if (zipInput.value.trim()) {
          storeResults.classList.add('active');
        }
      }
    });

    // Newsletter Signup
    const newsletterForm = document.getElementById('newsletterForm');
    const newsletterConfirmation = document.getElementById('newsletterConfirmation');

    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      newsletterForm.style.display = 'none';
      newsletterConfirmation.classList.add('active');
    });
  </script>

